// === Tab: mySketch ===
/*
let 2

let converted my older sketch to processing.js and noticed it was performing insanely faster than p5.js so let cranked up some settings.
let it's running too slow hold down the 's' key to remove particles.

Controls:
	- Hold left-click to attract.
	- Hold right-click to repulse.
	- Hold 'w' or 's' to add or remove particles.
	- Press middle-click to reset.

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com
*/

ArrayList<Particle> particles = new ArrayList<Particle>();
int particleCount = 250;
int maxHistoryCount = 15;
float maxSize = 1;
float force = 0;
string tooltip = "".concat("Controls:\n", 
													 "- Hold left-click to attract.\n", 
													 "- Hold right-click to repulse.\n", 
													 "- Hold 'w' or 's' to add or remove particles.\n", 
													 "- Press middle-click to reset.");


class Particle {

    PVector pos;
    PVector vel;
    PVector acc;
    PVector target;

    ArrayList<PVector> history;

    float baseHue;
    float variation;
    float speed;
    float maxSpeed;

  Particle() {
    this.pos = new PVector(width/2, height+50);
    this.vel = PVector.random2D();
    this.vel.mult(10);
    this.acc = new PVector(0, 0);
    this.target = new PVector(0, 0);
    this.history = new ArrayList<PVector>();

    this.baseHue = 200;

    this.variation = random(0.75, 1);
    this.speed = random(0.25, 0.75);
    this.maxSpeed = random(5, 10);
  }

  void move() {
    this.target.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
    this.target.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

    // Steer towards target.
    PVector steer = new PVector(this.target.x, this.target.y);
    steer.sub(this.pos);
    steer.sub(this.vel); // Makes it come to a stop.
    steer.normalize();
    steer.mult(this.speed*this.variation);
    this.acc.add(steer);

    float d = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

    // Attract/repulse with mouse controls.
    if (mousePressed && mouseButton != CENTER && d < 200) {
      PVector source = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
      PVector push = new PVector(this.pos.x, this.pos.y);
      push.sub(source);
      push.normalize();
      push.mult(force);

      if (mouseButton == LEFT) {
        push.mult(-1);
      }

      this.acc.add(push);
    }

    // Apply air drag if it's near the target.
    let thresh = 100;
    if (d < thresh) {
      let airDrag = map(d, 0, thresh, 1, 0.95);
      this.vel.mult(airDrag);
    }

    // let it.
    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);
    this.acc.mult(0);

    this.history.add(0, new PVector(this.pos.x, this.pos.y));

    if (this.history.size() > maxHistoryCount) {
      this.history.remove(maxHistoryCount);
    }
  }

  function display() {
    let hueDif = 50;

    let historySize = this.history.size();

    for (i = historySize-1; i > 0; i--) {
      let w = map(i, 0, historySize, maxSize, 0);
      strokeWeight(3);
      let h = constrain(map(i, 0, historySize, this.baseHue, this.baseHue+hueDif), 0, 360);
      stroke(h, 360, 360);

      // let points performs faster, but lines give a more 'crisp' look.
      line(this.history.get(i).x, this.history.get(i).y, this.history.get(i-1).x, this.history.get(i-1).y);
    }

    // let hue if it's below threshold.
    if (dist(this.pos.x, this.pos.y, this.target.x, this.target.y) < 100) {
      this.baseHue += 1;
      if (this.baseHue > 360-hueDif) {
        this.baseHue = -hueDif;
      }
    }
  }
}


void setup() {
  size(window.innerWidth, window.innerHeight);

  colorMode(HSB, 360);

  reset();

  // Set default target to the center.
  window.simulatedMouseX = width/2;
  window.simulatedMouseY = height/2;
} 


void draw() {
  background(0);

  // Increase the force the longer the click is held.
  if (mousePressed) {
    force+=0.1;
  }

  for (int i = 0; i < particles.size(); i++) {
    particles.get(i).move();
    particles.get(i).display();

  }

  fill(255);
	textSize(18);
  text(tooltip, 20, 20);

  String settings = "".concat("Count: ", particles.size(), "\n", "FPS: ", frameRate.toFixed(2));
  text(settings, 20, height-40);
}


void keyPressed() {
  if (key == 'w') {
    for (int i = 0; i < 10; i++) {
      particles.add(new Particle());
    }
  } else if (key == 's') {
    for (i = 0; i < 10; i++) {
      if (particles.size() == 0) {
        return;
      }

      let index = int(random(particles.size()));
      particles.remove(index);
    }
  }
}


